"",
":root{--bg:#05070a;--s1:#0d1319;--s2:#141c24;--s3:#1d2832;--line:#2a3745;--txt:#f5f7fa;--mut:#9aa8b8;--am:#ffb02e;--co:#ff6a4d;--ro:#ff5e7a;--in:#8b7bff;--up:#3ddc97;--dn:#ff5d73;--grad:linear-gradient(120deg,#ffc24d,#ff6a4d);--grad2:linear-gradient(120deg,#8b7bff,#5b6bff);color-scheme:dark;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px)}",
