".app{max-width:480px;margin:0 auto;min-height:100vh;padding:0 0 118px}",
".note{margin:8px 16px 0;padding:8px 11px;border-radius:10px;background:var(--s1);border:1px solid var(--line);color:var(--mut);font-size:11px;font-weight:600}",
"@keyframes in{from{opacity:0;transform:translateY(10px)}}@keyframes spin{to{rotate:360deg}}@keyframes pulse{50%{opacity:.35;transform:scale(.8)}}@keyframes flt{50%{translate:0 -5px}}@keyframes blink{50%{opacity:0}}@keyframes scan{0%,100%{top:8%}50%{top:88%}}@keyframes pop{from{transform:scale(.6);opacity:0}}@keyframes fu{from{background:#3ddc9733}}@keyframes fd{from{background:#ff5d7333}}@keyframes slide{from{opacity:0;transform:translateY(-8px)}}",
