".srch{position:relative;flex:1;min-width:0;height:42px;display:flex;align-items:center;gap:8px;padding:0 12px;border-radius:14px;background:var(--s2);font-weight:700;color:var(--mut);overflow:hidden;white-space:nowrap}",
".srch:before{content:\"\";position:absolute;inset:0;border-radius:inherit;padding:1.5px;background:conic-gradient(from var(--a),#ffb02e,#ff5e7a,#8b7bff,#ffb02e);-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;animation:rot 5s linear infinite;pointer-events:none}",
".srch svg{width:17px;height:17px;color:var(--am)}.srch .car{width:2px;height:15px;background:var(--am);animation:blink 1s steps(1) infinite;margin-left:-4px}",
