".tag{position:absolute;top:-6px;right:6px;background:var(--grad);color:#1b1006;font-size:8.5px;font-weight:800;padding:2px 5px;border-radius:6px}",
"/* banner */",
".banner{margin:14px 16px;padding:16px;border-radius:18px;background:radial-gradient(ellipse at 88% 30%,#2e1e0e,transparent 60%),linear-gradient(120deg,#10161d,#0a0f14);position:relative;overflow:hidden;min-height:108px}",
".banner:before{content:\"\";position:absolute;inset:0;border-radius:inherit;padding:1.5px;background:conic-gradient(from var(--a),#ffb02e,#ff5e7a,#8b7bff,#ffb02e);-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;animation:rot 7s linear infinite;pointer-events:none}",
".banner .chip{font:500 9.5px 'DM Mono',monospace;letter-spacing:.14em;color:var(--am)}.banner h3{margin:8px 0 3px;font-size:17px;max-width:62%}.banner p{margin:0;color:var(--mut);font-size:11.5px;max-width:60%}",
".orb{position:absolute;right:14px;top:12px;width:92px;height:92px;display:grid;place-items:center}",
".orb:before,.orb:after{content:\"\";position:absolute;border:1.5px solid #ffb02e77;border-radius:50%;animation:spin 10s linear infinite}",
".orb:before{width:92px;height:38px;transform:rotate(-30deg)}.orb:after{width:62px;height:92px;border-color:#8b7bff77;animation-direction:reverse;transform:rotate(40deg)}",
