".cta{position:absolute;right:14px;bottom:12px}",
"/* buttons */",
".btn,.pill{display:inline-flex;align-items:center;justify-content:center;gap:7px;padding:11px 22px;border-radius:0;clip-path:polygon(10px 0,100% 0,100% calc(100% - 10px),calc(100% - 10px) 100%,0 100%,0 10px);background:var(--grad);color:#1b1006;font-weight:800;font-size:13.5px}",
".btn.in{background:var(--grad2);color:#fff}.btn.sm{padding:8px 16px;font-size:12px}.btn.wide{width:100%}",
