".tabs button{color:var(--mut);font:800 15px 'Bricolage Grotesque',sans-serif;white-space:nowrap;padding:6px 0;position:relative}.tabs button.on{color:#fff;font-size:17px}",
".tabs button.on:after{content:\"\";position:absolute;left:0;bottom:-3px;width:20px;height:3.5px;border-radius:3px;background:var(--grad)}",
".sub{display:flex;gap:8px;padding:12px 16px 6px;overflow-x:auto;scrollbar-width:none}.sub button{white-space:nowrap;padding:7px 13px;border-radius:12px;background:var(--s2);border:1.5px solid var(--line);color:var(--mut);font-weight:700;font-size:12px}.sub button.on{background:#ffb02e1f;border-color:#ffb02e88;color:#ffc24d}",
