".fav:hover{transform:translateY(-2px)}.fav .ck{position:absolute;right:10px;top:10px;width:20px;height:20px;border-radius:6px;background:var(--grad);display:grid;place-items:center}.fav .ck svg{width:12px;height:12px;stroke:#1b1006;stroke-width:3.4}",
".fav b{display:block;font-size:14.5px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%;margin-top:4px}.fav .mt{color:var(--mut);font-size:10.5px;font-weight:700;margin-top:-2px}.fav .px{font:800 17px 'Bricolage Grotesque',sans-serif;margin-top:6px}",
