".live{margin-left:auto;display:flex;align-items:center;gap:6px;font:500 9px 'DM Mono',monospace;letter-spacing:.1em;color:var(--mut)}.live i,.dot{width:7px;height:7px;border-radius:50%;background:var(--am);box-shadow:0 0 8px var(--am);animation:pulse 1.8s infinite;display:inline-block}",
