".seg{display:flex;gap:6px;padding:4px 16px 10px;border-bottom:1.5px solid var(--line);margin-bottom:10px}.seg button{padding:8px 14px;border-radius:11px;color:var(--mut);font-weight:800}.seg button.on{background:#ffb02e22;color:#fff;border:1.5px solid #ffb02e66}",
".depthbar{display:flex;align-items:center;gap:8px;padding:0 16px 10px;font-size:12px;font-weight:800}.depthbar i{font-style:normal;border:1.5px solid;border-radius:4px;padding:0 5px;font-size:10px}.bar{flex:1;display:flex;gap:2px;height:7px}.bar span{border-radius:4px}",
