".cell{display:grid;grid-template-columns:1fr 1fr;height:25px;align-items:center;position:relative;font-variant-numeric:tabular-nums}.cell .d{position:absolute;top:1px;bottom:1px;opacity:.2}.cell>*{position:relative}",
".cell.b .d{right:0;background:var(--up)}.cell.a .d{left:0;background:var(--dn)}",
