".bsw{padding:4px 16px 10px}.bsp{display:inline-flex;background:var(--s2);border:1.5px solid var(--line);border-radius:15px;padding:3px}.bsp button{padding:8px 22px;border-radius:12px;color:var(--mut);font-weight:800;font-size:13.5px}",
