"/* portfolio */",
".cw{display:flex;align-items:center;gap:12px;margin:12px 16px 4px;padding:14px;border-radius:18px;background:linear-gradient(135deg,#8b7bff30,#0d1319 70%);border:1.5px solid #8b7bff66}.cw b{display:block;font-size:14.5px;font-weight:800}.cw small{color:var(--mut);font-weight:600}.cw div{flex:1}",
".wtabs{display:flex;gap:20px;padding:14px 16px 4px;overflow-x:auto}.wtabs button{color:var(--mut);font:800 15px 'Bricolage Grotesque',sans-serif}.wtabs button.on{color:#fff}",
