".pfr{display:flex;align-items:center;justify-content:space-between;padding:15px 16px;font-size:14.5px;font-weight:800;width:100%}.pfr span{display:flex;gap:12px;align-items:center}.pfr em{font-style:normal;color:var(--mut);display:flex;align-items:center;gap:4px}",
"/* dock nav */",
".nav{position:fixed;left:50%;transform:translateX(-50%);width:calc(100% - 24px);max-width:456px;bottom:calc(10px + env(safe-area-inset-bottom,0px));z-index:5;padding:7px 6px;border:1.5px solid #ffffff1f;border-radius:23px;background:#0b1015d9;backdrop-filter:blur(20px);box-shadow:0 14px 44px #000c}",
