".nav svg{width:25px;height:25px;padding:3px;border-radius:12px;transition:all .25s}.nav button.on svg{background:var(--grad);color:#1b1006;width:36px;height:29px;padding:4px 9px;box-shadow:0 6px 18px #ff6a4d66}",
".toast{position:fixed;left:50%;transform:translateX(-50%);bottom:106px;background:#1d2832;border:1.5px solid #ffffff22;padding:11px 15px;border-radius:13px;font-size:12.5px;font-weight:700;max-width:88%;text-align:center;z-index:99}",
