".avb{width:40px;height:42px;border-radius:13px;background:var(--s2);color:var(--txt);border:1px solid var(--line);box-shadow:none}.avb svg{width:20px;height:20px}",
".srch{font-weight:500}.srch input{font-weight:500}.srch:before{padding:1px}",
".ib{border-width:1px}",
".grid{gap:16px 4px}.opt{font-size:11px;font-weight:600;gap:7px}",
