".tag{font-weight:700}",
".banner{border-radius:16px;min-height:100px;background:radial-gradient(ellipse at 88% 30%,#2e1e0e,transparent 60%),linear-gradient(120deg,#17121f,#100c18)}.banner:before{padding:1px}.banner h3{font-size:15.5px;font-weight:700}.banner p{font-weight:500;font-size:11px}",
".btn,.pill{font-weight:700;font-size:13px;padding:10px 20px}.btn.sm{padding:8px 15px;font-size:12px}.btn.o,.pill.o{border-width:1px}",
