".fav b{font-size:14px;font-weight:700}.fav .mt{font-weight:600}.fav .px{font-size:16px;font-weight:700}",
".chg{font-weight:700}",
".row .nm b{font-size:13.5px;font-weight:700}.row .nm small{font-weight:500}.row .p{font-weight:700;font-size:13px}",
