".mcard{border-radius:16px;border-width:1px;font-weight:700;border-color:color-mix(in srgb,var(--ac) 22%,var(--line));background:linear-gradient(160deg,color-mix(in srgb,var(--ac) 12%,#15121f),#15121f 65%)}.mcard.on{border-color:var(--ac)}",
".sel select{font-size:18px;font-weight:700}.tpx b{font-size:22px;font-weight:700}",
".seg{border-bottom-width:1px}.seg button{font-weight:600}.seg button.on{border-width:1px}",
".bk,.tr{font-weight:600}.depthbar{font-weight:700}",
".rb div{border-width:1px}.rb b{font-weight:700;font-size:15px}",
".ptabs button.t{font-size:14px;font-weight:700}.cur{border-width:1px;font-weight:700;font-size:12px}",
".bsp{border-width:1px}.bsp button{font-weight:600;font-size:13px;padding:7px 20px}",
".filt{border-width:1px 0;font-weight:600;font-size:12px}.filt select,.filt input{font-weight:600;font-size:12px}",
".ad{border-bottom-width:1px;padding:12px 16px}.ad .who b{font-weight:700;font-size:13px}.ad .who small{font-weight:500}.ad .pr{font-size:17px;font-weight:700}.ad .kv{font-weight:500}.ad .kv b{font-weight:600}",
".cw{border-width:1px}.cw b{font-weight:700;font-size:14px}",
".wtabs button{font-weight:700;font-size:14.5px}.wval b{font-size:28px;font-weight:600}.pf{font-size:17px;font-weight:700}.pfr{font-weight:700;font-size:14px}",
".nav{border-width:1px;background:#120f1bd9}.nav button{font-weight:700}",
