".ph h2{font-size:16px;font-weight:700}.ph .bk2,.ph .rt{border-width:1px}",
".card{border-width:1px;border-radius:16px}.card h3{font-size:15px}.card p{font-weight:500}",
".lr{font-weight:600;font-size:14px}.lr .lic{border-width:1px}.lr small{font-weight:500}",
".pc{font-weight:700;border-width:1px;font-size:13.5px}.pill2{font-weight:700}",
