".wc{border-width:1px}.wi{font-weight:500}.rv{border-width:1px}",
".ftabs button{font-weight:700;font-size:15px}.msg{font-weight:500}",
"",
"/* ===== mature, flat styling (dark circles, flat orange, fixed bottom bar) ===== */",
":root{--bg:#050505;--s1:#121212;--s2:#1b1b1d;--s3:#262628;--line:#2a2a2d;--mut:#8e8e93;--txt:#fff;--am:#ff9f2e;--co:#ff9f2e;--grad:#ff9f2e;--grad2:#2a2a2d;--up:#12b76a;--dn:#f04452}",
"html,body{background:#050505}",
".num,.cell,.tr,.bk,.rb b,.tpx b,.row .p,.fav .px,.badge,.ad .pr,.wval b{font-variant-numeric:tabular-nums}",
".cell,.tr{contain:layout style}.row .p{min-width:96px}",
"/* header */",
".avb{width:40px;height:40px;border-radius:50%;background:#1b1b1d;border:0;color:#fff}",
".srch{background:#1b1b1d;border-radius:999px;height:42px;font-weight:500;color:#8e8e93}.srch:before{display:none}.srch svg{color:#fff}.srch .car{background:#8e8e93}",
".ib{background:none;border:0;width:34px;border-radius:50%}.ib svg{width:22px;height:22px;color:#fff}.ib i{border-color:#050505;background:#f04452}",
"/* option circles */",
".tile{width:48px;height:48px;border-radius:50%;background:#161616;border:0;color:#fff}.tile svg{width:22px;height:22px}",
".opt{font-weight:500;font-size:11.5px;color:#fff}.opt:hover .tile{box-shadow:none;transform:none}",
".tile.hl{color:#ff9f2e}",
".tag{background:#ff9f2e;color:#111;border-radius:6px}",
"/* buttons */",
".btn,.pill{clip-path:none;border-radius:999px;background:#ff9f2e;color:#111;font-weight:600;padding:11px 24px;font-size:13px}",
".btn.sm{padding:8px 18px;font-size:12px}.btn.in{background:#2a2a2d;color:#fff}",
".btn.o,.pill.o{background:#1f1f22;color:#fff;border:0}",
".btn.buy{background:#12b76a;color:#fff}.btn.sell{background:#f04452;color:#fff}",
".btn[disabled]{opacity:.4}",
".bsp{background:#1b1b1d;border:0;border-radius:999px;padding:3px}.bsp button{border-radius:999px;color:#8e8e93;font-weight:600}",
".bsp button.on[data-side=\"Buy\"]{background:#12b76a;color:#fff}.bsp button.on[data-side=\"Sell\"]{background:#f04452;color:#fff}",
".seg button.on{background:#2a2a2d;color:#fff;border:0}",
".sub button{background:#1b1b1d;border:0;border-radius:999px;color:#8e8e93;font-weight:600}.sub button.on{background:#2a2a2d;color:#fff}",
".tabs button.on:after,.ftabs button.on:after{background:#ff9f2e}",
".sw.on{background:#ff9f2e}",
"/* cards */",
".banner{background:#141414;border:1px solid #232326;border-radius:16px}.banner:before{display:none}.banner .chip{color:#ff9f2e}",
".orb:before,.orb:after{border-color:#ffffff1f;animation:none}.orb img{animation:none;filter:none}",
".fav{padding:10px 11px;gap:6px;border-radius:14px;background:#141414;border:1px solid #232326;position:relative;min-width:0}",
".favs{gap:8px}",
".fav .fh{display:flex;align-items:center;gap:8px;min-width:0;padding-right:20px;width:100%}",
".fav b{font-size:13px;margin:0;font-weight:600;min-width:0}",
".coin{background:var(--ac,#888);box-shadow:none}.coin.sm{width:24px;height:24px;border-radius:50%;font-size:11px}",
".fav .fp{display:flex;justify-content:space-between;align-items:baseline;gap:6px;width:100%}",
".fav .px{font-size:14.5px;margin:0;font-weight:700}.fav .mt{margin:0;font-size:10.5px;color:#8e8e93}.fav .chg{font-size:11.5px}",
".fav .ck{width:16px;height:16px;right:9px;top:9px;border-radius:5px;background:#ff9f2e}.fav .ck svg{width:10px;height:10px}",
".fav:hover{transform:none}",
".mcard{background:#121212;border:1px solid #232326;box-shadow:none}.mcard svg{color:#fff}.mcard:hover{transform:none}.mcard.on{background:#171717;border-color:#ff9f2e;box-shadow:none}",
".cw{background:#121212;border:1px solid #232326}",
".ctype{background:#121212;border-color:#232326}.ctype:hover{transform:none;border-color:#ff9f2e}",
".pc{background:#121212;border-color:#232326}.pc svg{color:#fff}",
".card{background:#121212;border-color:#232326}",
".lr .lic,.ncard .lic{background:#1b1b1d;border:0;color:#fff}",
".big{background:#ff9f2e;color:#111;box-shadow:none}",
".fld{background:#0c0c0c;border-color:#2a2a2d}.fld:focus-within{border-color:#ff9f2e;box-shadow:none}",
".chk{background:#0c0c0c}",
".stp.on{background:#141414}.stp.on i{background:#ff9f2e;border-color:#ff9f2e;box-shadow:none;color:#111}.stp.dn i{background:#2a2a2d;border-color:#ff9f2e;color:#ff9f2e}",
".wc{background:#101010}.wc .st{color:#ff9f2e}.wi svg{color:#ff9f2e}",
".pill2.ok{background:#12b76a22;color:#12b76a}.pill2.warn{background:#ff9f2e22;color:#ff9f2e}",
".live i,.dot{background:#ff9f2e;box-shadow:none;animation:none}",
".fl-u,.fl-d{animation:none}.view.enter>*{animation:none}",
".badge.up{background:#12b76a1f;border-color:#12b76a44}.badge.dn{background:#f044521f;border-color:#f0445244}",
"/* bottom bar: fixed to the screen, full width, no blur */",
".nav{left:0;right:0;transform:none;width:auto;max-width:none;bottom:0;border-radius:0;border-width:1px 0 0;border-color:#1f1f22;padding:8px 0 calc(8px + env(safe-area-inset-bottom,0px));background:#0a0a0a;backdrop-filter:none;-webkit-backdrop-filter:none;box-shadow:none;transform:translateZ(0)}",
".nav div{max-width:480px;margin:0 auto}",
".nav button{color:#7a7a80;font-weight:600}.nav button.on{color:#fff}",
".nav button.on svg{background:none;color:#fff;box-shadow:none;width:25px;height:25px;padding:3px}",
".app{padding-bottom:92px}",
".toast{bottom:84px;background:#262628}",
".ph{background:#050505;backdrop-filter:none;-webkit-backdrop-filter:none}",
".ph .bk2,.ph .rt{background:#1b1b1d;border:0}",
"",
".tile.hl{background:#161616;color:#ff9f2e;box-shadow:none}",
".fav .fh{padding-right:20px;gap:7px}.fav b{font-size:12.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}",
".coin.sm{width:22px;height:22px;font-size:10.5px;flex:none}",
".fav .px{font-size:13.5px;white-space:nowrap}.fav .mt{font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:46%;text-align:right}",
".fav .fp{align-items:center}",
