PG.deposit=function(){var tab=st.dtab||"Crypto",body;
 if(tab==="Fiat"){var o=ensureFiat(),f=st.fv;
  body=Fsel("fctry","Country (your account country)",CTRY,true)+Fsel("fcur","Currency",o.cur,true)+Fsel("fmeth","Payment method",o.meth,true)+Ftext("famt","Amount","0.00",true,"decimal")+
   '<div class="card" style="margin:0"><h3>Deposit summary</h3><div class="rv" style="margin-top:8px"><div><span>Country</span><b>'+esc(f.fctry)+'</b></div><div><span>Currency</span><b>'+esc(f.fcur)+'</b></div><div><span>Method</span><b>'+esc(f.fmeth)+'</b></div><div><span>Amount</span><b>'+(f.famt?esc(f.famt)+" "+esc(f.fcur):"—")+'</b></div></div></div>'+
   '<button class="btn wide" data-toast="Fiat deposits are not connected yet.">Get deposit details</button><p class="fine" style="padding:0">Methods shown are the ones commonly used in '+esc(f.fctry)+'. Only deposits from an account in your own name will be accepted.</p>'}
 else{var n=ensureNet("dast","dnet"),code=acode(st.fv.dast);
  body=Fsel("dast","Asset",ASSETS,true)+Fsel("dnet","Network",n.join("|"),true)+
   '<div class="card" style="margin:0"><h3>Deposit address</h3><p>Addresses appear once wallet and deposit tracking are enabled. Only blockchain-confirmed deposits will be credited.</p><button class="btn wide" disabled>Generate address</button></div>'+
   (MEMO[code]?'<div class="card" style="margin:0"><p style="margin:0">'+code+' deposits need a '+MEMO[code]+'. Include it or the deposit may not be credited.</p></div>':'')+
   '<p class="fine" style="padding:0">Only send '+code+' on the '+esc(st.fv.dnet)+' network. Funds sent on another network cannot be recovered.</p><button class="btn o wide" data-pg="connect">Connect a wallet instead</button>'}
 return hdr("Deposit")+'<div class="ftabs">'+["Crypto","Fiat"].map(function(t){return '<button class="'+(tab===t?"on":"")+'" data-act="dtab" data-arg="'+t+'">'+t+'</button>'}).join("")+'</div><div class="fs" style="padding:14px 16px">'+body+'</div>'};
