 var pz=$("#pz"),hd=$("#hd"),pw=$("#cpw"),ho=$("#ho"),W=pz.clientWidth,H=pz.clientHeight,mx=$("#tk").clientWidth-hd.offsetWidth,ST=Math.round(W*.04),hr=Math.round(Math.min(mx-2,W*(.74+Math.random()*.04)-ST)),hy=Math.round(H*.755-ho.offsetHeight/2),x=0,sx=0,dr=false;
 ho.style.left=(ST+hr)+"px";ho.style.top=hy+"px";pw.style.top=hy+"px";var bg="url("+CZ+")",cpc=$("#cpc");pz.style.background=bg+" center/100% 100%";cpc.style.background="linear-gradient(135deg,#ffffff55,#ffffff14),"+bg+" -"+(ST+hr)+"px -"+hy+"px/"+W+"px "+H+"px";
